INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 8, 'theory', 'Quiz: classes, prototypes and iterators');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 0, 'What does the engine do when a field is not found in the object itself?', '["Returns undefined at once", "Throws a ReferenceError", "Looks for it up the prototype chain until it meets null", "Copies the field from the global object"]', 2, 'Every object refers to a prototype; the lookup goes along the chain to null, which is why toString from Object.prototype is found on any object.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 1, 'What does typeof return for a class declared as class Point {}?', '["''class''", "''function''", "''object''", "''prototype''"]', 1, 'A class is a constructor function with syntactic sugar; you cannot call it without new.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 2, 'What happens when you access the field #balance outside the class (obj.#balance)?', '["A syntax error: the private field is not accessible from outside", "undefined is returned", "The value of the field is returned", "The field is created anew"]', 0, 'Names with a hash sign are truly private: they cannot be accessed from outside, even through square brackets.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 3, 'When must super() be called in the constructor of a child class?', '["After all uses of this", "Only if the parent has static methods", "Never: the engine calls it itself", "Before the first use of this"]', 3, 'The parent constructor creates the object: before super(), this does not exist yet, and accessing it gives a ReferenceError.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 4, 'What method must an object have to be used in for…of?', '["forEach()", "A method with the key Symbol.iterator that returns an iterator", "next() on the object itself", "A length property"]', 1, 'The iteration protocol: [Symbol.iterator]() returns an iterator with a next() method giving { value, done }. Generators write such methods more briefly.');
